from pathlib import Path
import json,html,shutil
root=Path('outputs/mock-batch-01');rows=[];cards=[];identities=[]
for i in range(1,6):
 folder=root/f'blueprint-{i:02d}'
 data=json.loads((folder/'layout.json').read_text())
 assert (folder/'mock.png').exists()
 identities.append(json.dumps({k:dict(cells=sorted(b['cells']),gate=b['gate']) for k,b in data['blocks'].items()},sort_keys=True))
 blocks=data['blocks'];cells=[tuple(c) for b in blocks.values() for c in b['cells']]
 assert len(cells)==len(set(cells))==54
 row=dict(blueprint=i,origin='Previously reviewed board study 03' if i==1 else 'New layout',occupancy_percent=84.375,occupied_cells=54,empty_cells=10,studs=216,initial_straight_exits=0,initial_single_piece_exit_routes=data['initial_blocks_with_exit_after_repositioning'],verified_route_drags=len(data['gestures']),render_attempts=2 if i==5 else 1,blueprint_validation='PASS under declared test rules',mock_review='Major footprints, empty pockets, gate placement and stud patterns visually consistent; not pixel-exact verified',production_approval='WITHHELD: gate behavior, camera-scale precision and ad timing unverified')
 rows.append(row)
 (folder/'review.json').write_text(json.dumps(row,indent=2))
 if i==5:
  (folder/'prompt-retry.txt').write_text((folder/'prompt.txt').read_text()+'\n'+(folder/'retry-addendum.txt').read_text())
 cards.append(f'''<section id="b{i}"><h2>Blueprint {i:02d} <span>{'reviewed layout' if i==1 else 'new layout'}</span></h2><div class="pair"><figure><a href="blueprint-{i:02d}/blueprint.png"><img src="blueprint-{i:02d}/blueprint.png"></a><figcaption>Exact geometry master</figcaption></figure><figure><a href="blueprint-{i:02d}/mock.png"><img src="blueprint-{i:02d}/mock.png"></a><figcaption>ImageGen mock {'— corrected attempt 2' if i==5 else '— attempt 1'}</figcaption></figure></div><p>54 filled / 10 empty · 216 studs · 0 immediate straight exits · {len(data['gestures'])} drags in the checked full-clear route (not proven minimum).</p><p>Blueprint: <b>structural checks passed</b>. Mock: <b>visual review only; final approval withheld</b>.</p><p><a href="blueprint-{i:02d}/layout.json">Level + solution</a> · <a href="blueprint-{i:02d}/prompt.txt">Original prompt</a> · <a href="blueprint-{i:02d}/review.json">Review</a>{' · <a href="blueprint-05/mock-v1-failed.png">Failed first render</a> · <a href="blueprint-05/prompt-retry.txt">Retry prompt</a>' if i==5 else ''}</p></section>''')
assert len(set(identities))==5
(root/'batch-review.json').write_text(json.dumps(rows,indent=2))
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CAD blueprint / mock review — five levels</title><style>body{margin:0;background:#101c34;color:#dce5f6;font:17px/1.55 system-ui}main{max-width:1250px;margin:auto;padding:35px}h1{line-height:1.1}a{color:#70d5ff}nav{position:sticky;top:0;padding:14px;background:#101c34ee;display:flex;gap:25px}section{padding:28px 0;border-top:1px solid #41506b}h2 span{font-size:15px;color:#9ab0d0;font-weight:400}.pair{display:grid;grid-template-columns:1fr 1fr;gap:18px}figure{margin:0}img{width:100%;display:block}figcaption{padding:10px;color:#adc4e3}.note{background:#243453;padding:20px;border-radius:10px}@media(max-width:650px){.pair{grid-template-columns:1fr}}</style><main><h1>Five blueprints → five rendered mocks</h1><p>8×8 boards · 84.4% occupancy · varied connected shapes · offset matching gates.</p><div class="note">All five blueprints passed structural and solution checks under straight-sliding, no-rotation, matching-gate rules. Repositioning is inside the board before a straight exit; partial-outside parking was not explored. The generated images are visual candidates, not exact production geometry. Raised gate strips still need an opening/animation specification, and these longer solutions do not validate the original 20-second brief.</div><nav>'''+''.join(f'<a href="#b{i}">{i:02d}</a>' for i in range(1,6))+'''<a href="prompt-contract.txt">Reusable instructions</a></nav>'''+''.join(cards)+'''<section><h2>What this batch taught us</h2><p>Providing the drawn board and its cell data produced close visual matches in this batch. Mock 5 initially failed the stud count (9 on yellow rather than 16); a retry with per-piece counts restored the visible 4×4 arrangement. That observation is saved for future prompts; it is not permanent model training or proof of a reliable success rate.</p><p>Review limitations: the shown images were visually compared for gross footprints, empty pockets, studs and gate placement. No pixel-level segmentation/tolerance audit or animation test was performed. Use the JSON as production geometry authority.</p></section></main></html>'''
(root/'review.html').write_text(page,encoding='utf-8')
shutil.make_archive('outputs/CAD-five-blueprints-and-mocks','zip',root)
print(json.dumps(rows,indent=2))
